
// Ensure hero background video loads without blocking LCP, with mobile autoplay and fallback controls
const initHeroVideo = () => {
  const video = document.getElementById('hero-bg-video') || document.querySelector('.hero-media video');
  if (!video) return;

  const toggleBtn = document.getElementById('hero-video-toggle');
  const updateToggleUI = (isPlaying) => {
    if (!toggleBtn) return;
    const playIcon = toggleBtn.querySelector('.video-icon-play');
    const pauseIcon = toggleBtn.querySelector('.video-icon-pause');
    if (playIcon && pauseIcon) {
      playIcon.style.display = isPlaying ? 'none' : 'block';
      pauseIcon.style.display = isPlaying ? 'block' : 'none';
      toggleBtn.setAttribute('aria-label', isPlaying ? 'Pause background video' : 'Play background video');
      toggleBtn.setAttribute('title', isPlaying ? 'Pause background video' : 'Play background video');
    }
  };

  // Respect user motion preferences: if reduced motion is requested, pause & keep poster
  if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    video.pause();
    updateToggleUI(false);
    return;
  }

  video.muted = true;
  video.defaultMuted = true;
  video.playsInline = true;
  video.setAttribute('muted', '');
  video.setAttribute('playsinline', '');
  video.setAttribute('webkit-playsinline', '');

  // Ensure source exists and is set
  const source = video.querySelector('source');
  if (source && source.dataset.src && !source.getAttribute('src')) {
    source.src = source.dataset.src;
  }
  if (!video.src && source && source.src) {
    video.src = source.src;
  }

  const attemptPlay = () => {
    const playPromise = video.play();
    if (playPromise !== undefined) {
      playPromise.then(() => {
        updateToggleUI(true);
      }).catch(() => {
        updateToggleUI(false);
        // Autoplay policy or power-saver blocked: unlock on first user gesture
        const unlock = () => {
          video.play().then(() => updateToggleUI(true)).catch(() => {});
          ['click', 'touchstart', 'scroll', 'keydown'].forEach((evt) => {
            window.removeEventListener(evt, unlock);
          });
        };
        ['click', 'touchstart', 'scroll', 'keydown'].forEach((evt) => {
          window.addEventListener(evt, unlock, { once: true, passive: true });
        });
      });
    }
  };

  if (toggleBtn) {
    toggleBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (video.paused) {
        video.play().then(() => updateToggleUI(true)).catch(() => {});
      } else {
        video.pause();
        updateToggleUI(false);
      }
    });
  }

  video.addEventListener('play', () => updateToggleUI(true));
  video.addEventListener('pause', () => updateToggleUI(false));

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', attemptPlay);
  } else {
    attemptPlay();
  }
};
initHeroVideo();


const navigation = document.querySelector('.nav');
const menuButton = document.querySelector('.menu');
const leadModal = document.querySelector('[data-lead-modal]');
const leadForm = leadModal?.querySelector('[data-lead-form]');
const leadStatus = leadModal?.querySelector('[data-lead-status]');
let lastFocusedElement;

// Helper to close mobile menu and restore normal page state
const closeMenu = () => {
  if (!navigation?.classList.contains('mobile-open')) return;
  navigation.classList.remove('mobile-open');
  menuButton?.setAttribute('aria-expanded', 'false');
  menuButton?.setAttribute('aria-label', 'Open menu');
  document.querySelectorAll('.nav-dropdown').forEach((dd) => {
    dd.classList.remove('is-open');
    dd.querySelector('button')?.setAttribute('aria-expanded', 'false');
  });
  document.body.classList.remove('mobile-menu-active');
};

// Helper to open mobile menu and lock background body scroll
const openMenu = () => {
  navigation?.classList.add('mobile-open');
  menuButton?.setAttribute('aria-expanded', 'true');
  menuButton?.setAttribute('aria-label', 'Close menu');
  document.body.classList.add('mobile-menu-active');
};

// Hamburger / Close toggle button
menuButton?.addEventListener('click', (e) => {
  e.preventDefault();
  e.stopPropagation();
  const isOpen = navigation?.classList.contains('mobile-open');
  if (isOpen) {
    closeMenu();
  } else {
    openMenu();
  }
});

// Programs accordion toggle: expand/collapse on tap, prevent navigation, animate arrow
document.querySelectorAll('.nav-dropdown').forEach((dropdownEl) => {
  const triggerBtn = dropdownEl.querySelector('button');
  if (!triggerBtn) return;
  
  triggerBtn.addEventListener('click', (e) => {
    if (navigation?.classList.contains('mobile-open') || window.innerWidth <= 960) {
      e.preventDefault();
      e.stopPropagation();
      const isExpanded = dropdownEl.classList.toggle('is-open');
      triggerBtn.setAttribute('aria-expanded', String(isExpanded));
    }
  });
});

// Close when clicking outside header
document.addEventListener('click', (e) => {
  if (navigation?.classList.contains('mobile-open') && !navigation.contains(e.target)) {
    closeMenu();
  }
});

// Lock background scrolling while mobile menu is open, but allow menu links to scroll smoothly
document.addEventListener('touchmove', (e) => {
  if (document.body.classList.contains('mobile-menu-active')) {
    if (e.target.closest('.nav-links')) {
      return; // Allow scrolling inside the menu drawer
    }
    e.preventDefault(); // Lock background page scroll
  }
}, { passive: false });

// Floating header & announcement topbar scroll handling
const floatingHeader = document.querySelector('.floating-header');
const announcementTopbar = document.querySelector('.topbar');
if (floatingHeader) {
  let isScrolled = false;
  const handleHeaderScroll = () => {
    const shouldBeScrolled = window.scrollY > 15;
    if (shouldBeScrolled !== isScrolled) {
      isScrolled = shouldBeScrolled;
      floatingHeader.classList.toggle('is-scrolled', isScrolled);
      announcementTopbar?.classList.toggle('is-hidden', isScrolled);
    }
  };
  window.addEventListener('scroll', handleHeaderScroll, { passive: true });
  handleHeaderScroll();
}

// Close menu when navigating links (except accordion trigger)
navigation?.querySelectorAll('.nav-links a, .nav-cta').forEach((link) => {
  link.addEventListener('click', () => {
    closeMenu();
  });
});
document.addEventListener('keydown', (event) => {
  if (event.key === 'Escape') closeMenu();
  if (event.key === 'Escape' && leadModal?.classList.contains('is-open')) setLeadModal(false);
});

const setLeadModal = (isOpen) => {
  if (!leadModal) return;
  leadModal.classList.toggle('is-open', isOpen);
  leadModal.setAttribute('aria-hidden', String(!isOpen));
  document.body.classList.toggle('modal-open', isOpen);
  if (isOpen) {
    lastFocusedElement = document.activeElement;
    leadModal.querySelector('input')?.focus();
  } else {
    lastFocusedElement?.focus?.();
  }
};

const openLeadModal = (event) => {
  if (!leadModal) return;
  if (event && event.preventDefault) event.preventDefault();

  // Extract course from clicked trigger or parent button/card
  const trigger = event?.currentTarget || event?.target;
  const rawCourse = trigger?.getAttribute('data-course') ||
                    trigger?.getAttribute('data-lead-course') ||
                    trigger?.closest('[data-course]')?.getAttribute('data-course') ||
                    '';

  const courseSelect = leadModal.querySelector('#lead-course');
  if (courseSelect) {
    if (rawCourse) {
      const normalized = (window.EdnexLeadService && typeof window.EdnexLeadService.normalizeCourseTitle === 'function')
        ? window.EdnexLeadService.normalizeCourseTitle(rawCourse)
        : rawCourse;

      let matched = false;
      for (const opt of courseSelect.options) {
        if (opt.value && (opt.value.toLowerCase() === normalized.toLowerCase() || opt.value.toLowerCase().includes(normalized.toLowerCase()))) {
          opt.selected = true;
          matched = true;
          break;
        }
      }
      if (!matched && normalized) {
        // Find best match or select first corresponding
        for (const opt of courseSelect.options) {
          if (opt.text && opt.text.toLowerCase().includes(normalized.toLowerCase())) {
            opt.selected = true;
            matched = true;
            break;
          }
        }
      }
    } else {
      // General button: let user choose
      courseSelect.selectedIndex = 0;
    }
  }

  // Clear previous errors
  if (leadStatus) {
    leadStatus.textContent = '';
    leadStatus.className = 'lead-form-status';
  }

  setLeadModal(true);
};

document.querySelectorAll('a[href="#contact"], a[href="index.html#contact"], [data-lead-open]').forEach((link) => {
  link.addEventListener('click', openLeadModal);
});
leadModal?.querySelectorAll('[data-lead-close], [data-lead-later]').forEach((control) => {
  control.addEventListener('click', () => {
    if (control.hasAttribute('data-lead-later')) {
      try { sessionStorage.setItem('ednex-lead-dismissed', 'true'); } catch (e) {}
    }
    setLeadModal(false);
  });
});

// Resilient event delegation for modal open & close across all viewports & dynamic elements
document.addEventListener('click', (event) => {
  const openTrigger = event.target.closest('a[href="#contact"], a[href="index.html#contact"], [data-lead-open]');
  if (openTrigger && leadModal) {
    openLeadModal(event);
    return;
  }

  const closeTrigger = event.target.closest('[data-lead-close], [data-lead-later]');
  if (closeTrigger && leadModal && leadModal.classList.contains('is-open')) {
    if (closeTrigger.hasAttribute('data-lead-later')) {
      try { sessionStorage.setItem('ednex-lead-dismissed', 'true'); } catch (e) {}
    }
    setLeadModal(false);
  }
});
leadForm?.addEventListener('submit', async (event) => {
  event.preventDefault();

  const data = new FormData(leadForm);
  const honeypot = String(data.get('_hp_security_check') || '').trim();
  if (honeypot) {
    // Honeypot trapped automated bot: drop silently without sending
    console.warn('[Ednex Security] Bot submission suppressed via honeypot.');
    leadForm.reset();
    setLeadModal(false);
    return;
  }

  const name = String(data.get('name') || '').trim();
  const mobile = String(data.get('mobile') || '').trim();
  const email = String(data.get('email') || '').trim();
  const course = String(data.get('course') || '').trim();

  const showError = (msg, inputId) => {
    if (leadStatus) {
      leadStatus.textContent = msg;
      leadStatus.className = 'lead-form-status is-error';
    }
    if (inputId) {
      const input = leadForm.querySelector(`#${inputId}`);
      if (input) {
        input.focus();
        input.style.borderColor = 'var(--red, #c81e2b)';
        setTimeout(() => { input.style.borderColor = ''; }, 2500);
      }
    }
  };

  // 1. Validate Full Name
  if (!name || name.length < 2) {
    showError('Please enter your full name.', 'lead-name');
    return;
  }

  // 2. Validate Mobile Number (10 digits starting with 6-9)
  let cleanPhone = mobile.replace(/\D/g, '');
  if (cleanPhone.length === 12 && cleanPhone.startsWith('91')) {
    cleanPhone = cleanPhone.slice(2);
  } else if (cleanPhone.length === 11 && cleanPhone.startsWith('0')) {
    cleanPhone = cleanPhone.slice(1);
  }
  if (!cleanPhone || cleanPhone.length !== 10 || !/^[6-9]\d{9}$/.test(cleanPhone)) {
    showError('Please enter a valid 10-digit mobile number (e.g. 9876543210).', 'lead-mobile');
    return;
  }

  // 3. Validate Email Address
  if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    showError('Please enter a valid email address.', 'lead-email');
    return;
  }

  // 4. Validate Interested Course
  if (!course || course === '' || course === 'Select a program') {
    showError('Please select your interested course.', 'lead-course');
    return;
  }

  // Clear errors and prevent multiple accidental submissions
  if (leadStatus) {
    leadStatus.textContent = '';
    leadStatus.className = 'lead-form-status';
  }

  const submitBtn = leadForm.querySelector('button[type="submit"]');
  const originalBtnHtml = submitBtn ? submitBtn.innerHTML : 'Submit Enquiry &rarr;';
  const formInputs = leadForm.querySelectorAll('input, select, textarea, button');
  leadForm.setAttribute('aria-busy', 'true');
  formInputs.forEach((el) => { el.disabled = true; });
  if (submitBtn) {
    submitBtn.textContent = 'Opening WhatsApp...';
  }

  const payload = {
    name,
    phone: cleanPhone,
    mobile: cleanPhone,
    email,
    course,
    channel: 'website-modal',
    timestamp: new Date().toISOString()
  };

  // Open WhatsApp immediately inside user gesture to avoid popup blockers
  let whatsappUrl = `https://wa.me/918755803814`;
  if (window.EdnexLeadService && typeof window.EdnexLeadService.openWhatsApp === 'function') {
    whatsappUrl = window.EdnexLeadService.openWhatsApp(payload);
    const lines = [
      'Hello Ednex Academy! I would like to enquire about your programs.',
      '',
      `Name: ${name}`,
      `Mobile: ${cleanPhone}`
    ];
    if (email) {
      lines.push(`Email: ${email}`);
    }
    lines.push(`Interested Program: ${course}`);
    lines.push('');
    lines.push('Please share the course details and next steps.');
    lines.push('');
    lines.push('Thank you!');
    whatsappUrl = `https://wa.me/918755803814?text=${encodeURIComponent(lines.join('\n'))}`;
    const isMobile = /Android|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
    if (isMobile) {
      window.location.href = whatsappUrl;
    } else {
      const waWin = window.open(whatsappUrl, '_blank', 'noopener,noreferrer');
      if (!waWin || waWin.closed || typeof waWin.closed === 'undefined') {
        window.location.href = whatsappUrl;
      }
    }
  }

  // Dispatch to Google Sheets & Hostinger backend asynchronously in parallel
  try {
    if (window.EdnexLeadService && typeof window.EdnexLeadService.submitLead === 'function') {
      await window.EdnexLeadService.submitLead(payload);
    } else {
      await fetch('api/lead.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      }).catch(() => {});
    }
  } catch (err) {
    console.warn('[Ednex Lead] Notice dispatching lead data:', err);
  } finally {
    leadForm.removeAttribute('aria-busy');
    formInputs.forEach((el) => { el.disabled = false; });
    // Reset form and dismiss lead modal
    leadForm.reset();
    setLeadModal(false);
    if (submitBtn) {
      submitBtn.innerHTML = originalBtnHtml;
    }
    // Show dedicated Thank You modal with WhatsApp fallback button
    if (window.EdnexLeadService && typeof window.EdnexLeadService.showThankYouModal === 'function') {
      window.EdnexLeadService.showThankYouModal(whatsappUrl, course);
    }
  }
});

if (leadModal && !sessionStorage.getItem('ednex-lead-dismissed')) {
  window.setTimeout(() => setLeadModal(true), 1500);
}

const careerCarousel = document.querySelector('[data-career-carousel]');

if (careerCarousel) {
  const careerPathData = [
    { title: 'SEO Specialist', salary: '₹4–7+ LPA fresher · ₹10–18+ LPA experienced', image: 'cards/seo-specialist.png', link: 'digital-marketing.html' },
    { title: 'Performance Marketing Specialist', salary: '₹5–7+ LPA fresher · ₹10–20+ LPA experienced', image: 'cards/card2_pages-to-jpg-0002.jpg', link: 'digital-marketing.html' },
    { title: 'Data Analyst', salary: '₹5–7+ LPA fresher · ₹9–18+ LPA experienced', image: 'cards/BI Analyst.jpeg', link: 'data-analyst.html' },
    { title: 'AI/ML Developer', salary: '₹5–9+ LPA fresher · ₹12–22+ LPA experienced', image: 'cards/Ai ML.jpeg', link: 'artificial-intelligence.html' },
    { title: 'AI Engineer', salary: '₹5–10+ LPA fresher · ₹12–20+ LPA experienced', image: 'cards/card2_pages-to-jpg-0005.jpg', link: 'artificial-intelligence.html' },
    { title: 'Machine Learning Engineer', salary: '₹5–10+ LPA fresher · ₹12–20+ LPA experienced', image: 'cards/card2_pages-to-jpg-0006.jpg', link: 'artificial-intelligence.html' },
    { title: 'Cybersecurity Analyst', salary: '₹5–7+ LPA fresher · ₹9–18+ LPA experienced', image: 'cards/card2_pages-to-jpg-0007.jpg', link: 'cybersecurity.html' },
    { title: 'Security Engineer', salary: '₹5–9+ LPA fresher · ₹12–20+ LPA experienced', image: 'cards/card2_pages-to-jpg-0008.jpg', link: 'cybersecurity.html' }
  ];
  const track = careerCarousel.querySelector('[data-career-track]');
  const viewport = careerCarousel.querySelector('.career-viewport');
  const previousButton = document.querySelector('[data-career-prev]');
  const nextButton = document.querySelector('[data-career-next]');
  const dotsContainer = careerCarousel.querySelector('[data-career-dots]');
  const status = careerCarousel.querySelector('[data-career-status]');
  const sourceCards = [...track.querySelectorAll('[data-career-card]')];
  const totalCards = sourceCards.length;
  const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
  const cardGap = 22;
  let visibleCards = 3;
  let slideWidth = 0;
  let currentIndex = totalCards;
  let autoPlayTimer;
  let resumeTimer;
  let pointerStartX = 0;
  let pointerStartTranslate = 0;
  let isDragging = false;

  sourceCards.forEach((card, index) => {
    const career = careerPathData[index];
    if (!career) return;
    card.dataset.careerTitle = career.title;
    card.querySelector('.career-salary span').textContent = career.salary || 'To be verified and sourced';
  });

  const getVisibleCards = () => window.innerWidth <= 650 ? 1 : window.innerWidth <= 900 ? 2 : 3;
  const getStep = () => slideWidth + cardGap;
  const getTranslate = () => -(currentIndex * getStep());
  const setTransition = (enabled) => {
    track.style.transition = enabled && !prefersReducedMotion.matches ? 'transform .45s cubic-bezier(.22,.61,.36,1)' : 'none';
  };
  const updateVisualState = () => {
    const realIndex = ((currentIndex % totalCards) + totalCards) % totalCards;
    const activeOffset = Math.floor((visibleCards - 1) / 2);
    [...track.querySelectorAll('.career-card')].forEach((card, index) => {
      card.classList.toggle('is-active', index === currentIndex + activeOffset);
    });
    if (dotsContainer) {
      [...dotsContainer.children].forEach((dot, index) => dot.classList.toggle('is-active', index === realIndex));
    }
    if (status) {
      status.textContent = `${realIndex + 1} of ${totalCards}`;
    }
  };
  const moveTo = (index, animate = true) => {
    currentIndex = index;
    setTransition(animate);
    track.style.transform = `translate3d(${getTranslate()}px, 0, 0)`;
    updateVisualState();
  };
  const buildCarousel = () => {
    visibleCards = getVisibleCards();
    const cards = sourceCards.map((card) => card.cloneNode(true));
    track.innerHTML = '';
    const viewportStyles = getComputedStyle(viewport);
    const pLeft = parseFloat(viewportStyles.paddingLeft) || 0;
    const pRight = parseFloat(viewportStyles.paddingRight) || 0;
    const viewportWidth = viewport.clientWidth - pLeft - pRight;
    slideWidth = (viewportWidth - (visibleCards - 1) * cardGap) / visibleCards;
    
    // Create 3 complete sets: prepend clones, middle real set, append clones
    const loopCards = [];
    cards.forEach((card) => loopCards.push(card.cloneNode(true)));
    cards.forEach((card) => loopCards.push(card.cloneNode(true)));
    cards.forEach((card) => loopCards.push(card.cloneNode(true)));

    loopCards.forEach((card, index) => {
      card.style.flex = `0 0 ${slideWidth}px`;
      card.style.width = `${slideWidth}px`;
      card.style.maxWidth = `${slideWidth}px`;
      card.style.minWidth = '0';
      card.querySelector('img')?.setAttribute('loading', 'eager');
      card.setAttribute('aria-hidden', String(index < totalCards || index >= totalCards * 2));
      track.appendChild(card);
    });

    if (dotsContainer) {
      dotsContainer.innerHTML = '';
      sourceCards.forEach((card, index) => {
        const dot = document.createElement('button');
        dot.type = 'button';
        dot.className = 'career-dot';
        dot.setAttribute('aria-label', `Show ${card.dataset.careerTitle}`);
        dot.addEventListener('click', () => {
          moveTo(totalCards + index);
          pauseAndResume();
        });
        dotsContainer.appendChild(dot);
      });
    }
    moveTo(totalCards, false);
  };
  const pause = () => {
    window.clearInterval(autoPlayTimer);
    window.clearTimeout(resumeTimer);
  };
  const start = () => {
    pause();
    if (!prefersReducedMotion.matches && !document.hidden) {
      autoPlayTimer = window.setInterval(() => moveTo(currentIndex + 1), 2600);
    }
  };
  const pauseAndResume = () => {
    pause();
    if (!prefersReducedMotion.matches) resumeTimer = window.setTimeout(start, 5000);
  };
  const moveBy = (amount) => {
    moveTo(currentIndex + amount);
    pauseAndResume();
  };

  track.addEventListener('transitionend', (event) => {
    if (event.propertyName !== 'transform') return;
    if (currentIndex >= totalCards * 2) {
      moveTo(currentIndex - totalCards, false);
    } else if (currentIndex < totalCards) {
      moveTo(currentIndex + totalCards, false);
    }
  });
  previousButton?.addEventListener('click', () => moveBy(-1));
  nextButton?.addEventListener('click', () => moveBy(1));
  viewport.addEventListener('mouseenter', pause);
  viewport.addEventListener('mouseleave', start);
  viewport.addEventListener('pointerdown', (event) => {
    isDragging = true;
    pointerStartX = event.clientX;
    pointerStartTranslate = getTranslate();
    pause();
    track.classList.add('is-dragging');
    viewport.setPointerCapture(event.pointerId);
  });
  viewport.addEventListener('pointermove', (event) => {
    if (!isDragging) return;
    track.style.transform = `translate3d(${pointerStartTranslate + event.clientX - pointerStartX}px, 0, 0)`;
  });
  const finishDrag = (event) => {
    if (!isDragging) return;
    isDragging = false;
    track.classList.remove('is-dragging');
    const delta = event.clientX - pointerStartX;
    const threshold = Math.max(40, getStep() * 0.16);
    if (Math.abs(delta) > threshold) currentIndex += delta < 0 ? 1 : -1;
    moveTo(currentIndex);
    pauseAndResume();
  };
  viewport.addEventListener('pointerup', finishDrag);
  viewport.addEventListener('pointercancel', finishDrag);
  document.addEventListener('visibilitychange', () => document.hidden ? pause() : start());
  window.addEventListener('resize', buildCarousel);
  prefersReducedMotion.addEventListener?.('change', () => {
    buildCarousel();
    start();
  });
  buildCarousel();
  start();
}

const roleDiscovery = document.querySelector('[data-role-discovery]');
const roleSearch = document.querySelector('#role-search');
const roleOptions = document.querySelector('#role-options');
const roleRotator = document.querySelector('[data-role-rotator]');
const findRoleButtons = document.querySelectorAll('[data-find-role]');
const findRoleButton = findRoleButtons[0] || null;

if (roleDiscovery && roleSearch && roleOptions && roleRotator && findRoleButtons.length) {
  // Clean, verified mapping from job role to existing Ednex program URLs
  const roleRoutes = {
    'Digital Marketing Executive': 'digital-marketing.html',
    'Data Analyst': 'data-analyst.html',
    'AI Associate': 'artificial-intelligence.html',
    'Cyber Security Analyst': 'cybersecurity.html',
    'Marketing Analyst': 'digital-marketing.html',
    'Full-Stack Web Development': 'web-development.html',
    'Full-Stack Web Developer': 'web-development.html'
  };

  const rotatingRoles = [
    'a Digital Marketing Executive',
    'a Data Analyst',
    'an AI Associate',
    'a Cyber Security Analyst',
    'a Marketing Analyst'
  ];

  const roles = Object.keys(roleRoutes);
  let selectedRole = '';
  let activeOptionIndex = -1;
  let roleIndex = 0;
  let roleTimer = null;
  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
  const noResultsEl = roleOptions.querySelector('#role-no-results');
  const noResultsQuery = roleOptions.querySelector('#role-no-results-query');

  /* ── 1. Typewriter Animation inside Search Bar Placeholder ──
     Cycles through prompt and existing course/career names character-by-character.
     Pauses on focus/typing, resumes when cleared & blurred. Respects reduced-motion.
  ───────────────────────────────────────────────────────────── */
  const initHeroSearchTypewriter = () => {
    const defaultPrompt = 'Which job do you want to get?';
    if (reducedMotion.matches) {
      roleSearch.setAttribute('placeholder', defaultPrompt);
      return;
    }

    const phrases = [
      defaultPrompt,
      'Digital Marketing Executive',
      'Data Analyst',
      'AI Associate',
      'Cyber Security Analyst',
      'Marketing Analyst'
    ];

    let phraseIdx = 0;
    let charIdx = phrases[0].length;
    let isDeleting = false;
    let isPaused = false;
    let typingTimer = null;

    roleSearch.setAttribute('placeholder', phrases[0]);

    const typeSpeed = 65;
    const deleteSpeed = 32;
    const holdPrompt = 2200;
    const holdPhrase = 1800;
    const pauseBeforeType = 350;

    const step = () => {
      if (isPaused) return;

      const current = phrases[phraseIdx];
      if (isDeleting) {
        charIdx--;
        roleSearch.setAttribute('placeholder', current.substring(0, charIdx));
        if (charIdx <= 0) {
          isDeleting = false;
          phraseIdx = (phraseIdx + 1) % phrases.length;
          typingTimer = window.setTimeout(step, pauseBeforeType);
          return;
        }
        typingTimer = window.setTimeout(step, deleteSpeed);
      } else {
        charIdx++;
        roleSearch.setAttribute('placeholder', current.substring(0, charIdx));
        if (charIdx >= current.length) {
          isDeleting = true;
          const hold = phraseIdx === 0 ? holdPrompt : holdPhrase;
          typingTimer = window.setTimeout(step, hold);
          return;
        }
        typingTimer = window.setTimeout(step, typeSpeed);
      }
    };

    typingTimer = window.setTimeout(() => {
      isDeleting = true;
      step();
    }, holdPrompt);

    const pause = () => {
      isPaused = true;
      if (typingTimer) window.clearTimeout(typingTimer);
    };

    const resume = () => {
      if (roleSearch.value.trim() !== '' || document.activeElement === roleSearch) {
        return;
      }
      isPaused = false;
      if (typingTimer) window.clearTimeout(typingTimer);
      step();
    };

    roleSearch.addEventListener('focus', pause);
    roleSearch.addEventListener('blur', resume);
    roleSearch.addEventListener('input', pause);

    document.addEventListener('visibilitychange', () => {
      if (document.hidden) pause();
      else resume();
    });
  };

  initHeroSearchTypewriter();

  /* ── 2. Dropdown Visibility & Option Highlighting ── */
  const setOptionsOpen = (isOpen) => {
    roleOptions.classList.toggle('is-open', isOpen);
    roleSearch.setAttribute('aria-expanded', String(isOpen));
    if (!isOpen) {
      activeOptionIndex = -1;
      updateActiveOptionHighlight();
    }
  };

  const getVisibleOptions = () => {
    return [...roleOptions.querySelectorAll('.role-option[data-role]')].filter((opt) => !opt.hidden);
  };

  const updateActiveOptionHighlight = () => {
    const visible = getVisibleOptions();
    visible.forEach((opt, idx) => {
      const isActive = idx === activeOptionIndex;
      opt.classList.toggle('is-active-option', isActive);
      if (isActive) {
        roleSearch.setAttribute('aria-activedescendant', opt.id || '');
      }
    });
    if (activeOptionIndex === -1) {
      roleSearch.removeAttribute('aria-activedescendant');
    }
  };

  const updateSelectedState = () => {
    document.querySelectorAll('[data-role]').forEach((control) => {
      const isSelected = control.dataset.role === selectedRole;
      control.classList.toggle('is-selected', isSelected);
      if (control.classList.contains('role-chip')) {
        control.setAttribute('aria-pressed', String(isSelected));
      }
      if (control.getAttribute('role') === 'option') {
        control.setAttribute('aria-selected', String(isSelected));
      }
    });
  };

  const chooseRole = (role, navigate = true) => {
    const targetUrl = roleRoutes[role];
    if (!targetUrl) return;
    selectedRole = role;
    roleSearch.value = role;
    updateSelectedState();
    setOptionsOpen(false);

    // Sync headline rotator to chosen role
    const words = roleRotator?.querySelectorAll('.role-rotator-word');
    if (words && words.length) {
      words.forEach((word, idx) => {
        const matches = word.dataset.role === role;
        word.classList.toggle('is-active', matches);
        if (matches) roleIndex = idx;
      });
    }

    if (navigate && targetUrl) {
      window.location.href = targetUrl;
    }
  };

  const rotateRole = () => {
    if (reducedMotion.matches || document.hidden || !roleRotator) return;
    const words = roleRotator.querySelectorAll('.role-rotator-word');
    if (!words.length) return;
    roleIndex = (roleIndex + 1) % words.length;
    words.forEach((word, idx) => {
      word.classList.toggle('is-active', idx === roleIndex);
    });
  };

  /* ── 3. Option Selection via Click ── */
  roleOptions.addEventListener('click', (event) => {
    const advisorBtn = event.target.closest('.role-no-results-btn');
    if (advisorBtn) {
      setOptionsOpen(false);
      return;
    }
    const option = event.target.closest('.role-option[data-role]');
    if (option) {
      const href = option.getAttribute('href') || roleRoutes[option.dataset.role];
      if (href) {
        event.preventDefault();
        window.location.href = href;
      }
    }
  });

  /* ── 4. Chip Selection via Click (Supports Desktop & Mobile Marquee) ── */
  const chipsSection = document.querySelector('.role-chips-section');
  if (chipsSection) {
    chipsSection.addEventListener('click', (event) => {
      if (window.__roleSliderDragging) {
        event.preventDefault();
        return;
      }
      // If user tapped a chip, let the native link navigate
    });
  }

  /* ── 5. Filtering & Search Input Interactions ── */
  const filterSuggestions = () => {
    const query = roleSearch.value.trim().toLowerCase();
    let matchCount = 0;
    const options = roleOptions.querySelectorAll('.role-option[data-role]');

    options.forEach((option) => {
      const roleName = (option.dataset.role || '').toLowerCase();
      const title = (option.querySelector('.role-option-title')?.textContent || '').toLowerCase();
      const program = (option.querySelector('.role-option-program')?.textContent || '').toLowerCase();
      const matches = !query || roleName.includes(query) || title.includes(query) || program.includes(query);
      option.hidden = !matches;
      if (matches) matchCount++;
    });

    if (noResultsEl) {
      noResultsEl.hidden = matchCount > 0;
      if (noResultsQuery) {
        noResultsQuery.textContent = roleSearch.value.trim();
      }
    }

    selectedRole = roles.find((role) => role.toLowerCase() === query) || '';
    updateSelectedState();
    activeOptionIndex = -1;
    updateActiveOptionHighlight();
    setOptionsOpen(true);
  };

  roleSearch.addEventListener('focus', () => {
    filterSuggestions();
  });

  roleSearch.addEventListener('input', () => {
    filterSuggestions();
  });

  /* ── 6. Keyboard Navigation (ArrowDown, ArrowUp, Enter, Escape) ── */
  roleSearch.addEventListener('keydown', (event) => {
    const visible = getVisibleOptions();
    if (event.key === 'Escape') {
      setOptionsOpen(false);
    } else if (event.key === 'ArrowDown') {
      event.preventDefault();
      if (!roleOptions.classList.contains('is-open')) {
        setOptionsOpen(true);
      }
      if (visible.length > 0) {
        activeOptionIndex = (activeOptionIndex + 1) % visible.length;
        updateActiveOptionHighlight();
        visible[activeOptionIndex].scrollIntoView({ block: 'nearest' });
      }
    } else if (event.key === 'ArrowUp') {
      event.preventDefault();
      if (!roleOptions.classList.contains('is-open')) {
        setOptionsOpen(true);
      }
      if (visible.length > 0) {
        activeOptionIndex = (activeOptionIndex - 1 + visible.length) % visible.length;
        updateActiveOptionHighlight();
        visible[activeOptionIndex].scrollIntoView({ block: 'nearest' });
      }
    } else if (event.key === 'Enter') {
      event.preventDefault();
      if (activeOptionIndex >= 0 && visible[activeOptionIndex]) {
        const dest = visible[activeOptionIndex].getAttribute('href') || roleRoutes[visible[activeOptionIndex].dataset.role];
        if (dest) window.location.href = dest;
      } else if (visible.length > 0) {
        const dest = visible[0].getAttribute('href') || roleRoutes[visible[0].dataset.role];
        if (dest) window.location.href = dest;
      } else if (selectedRole && roleRoutes[selectedRole]) {
        window.location.href = roleRoutes[selectedRole];
      } else {
        const query = roleSearch.value.trim().toLowerCase();
        const matched = roles.find((r) => r.toLowerCase().includes(query));
        if (matched && roleRoutes[matched]) {
          window.location.href = roleRoutes[matched];
        } else {
          roleSearch.classList.add('is-pulsing');
          window.setTimeout(() => roleSearch.classList.remove('is-pulsing'), 600);
        }
      }
    }
  });

  // Close dropdown on outside click
  document.addEventListener('click', (event) => {
    if (!roleDiscovery.contains(event.target)) setOptionsOpen(false);
  });

  /* ── 7. Primary CTA: Find My Role / Arrow Button ── */
  const handleFindRole = (event) => {
    event.preventDefault();
    if (selectedRole && roleRoutes[selectedRole]) {
      window.location.href = roleRoutes[selectedRole];
      return;
    }
    const visible = getVisibleOptions();
    if (visible.length > 0) {
      const target = (activeOptionIndex >= 0 && visible[activeOptionIndex]) ? visible[activeOptionIndex] : visible[0];
      const dest = target.getAttribute('href') || roleRoutes[target.dataset.role];
      if (dest) {
        window.location.href = dest;
        return;
      }
    }
    const query = roleSearch.value.trim().toLowerCase();
    if (query) {
      const matched = roles.find((r) => r.toLowerCase().includes(query));
      if (matched && roleRoutes[matched]) {
        window.location.href = roleRoutes[matched];
        return;
      }
    }
    // If empty or no match, focus input, open options, and trigger attention pulse
    roleSearch.focus();
    filterSuggestions();
    roleSearch.classList.add('is-pulsing');
    window.setTimeout(() => roleSearch.classList.remove('is-pulsing'), 600);
  };
  findRoleButtons.forEach((btn) => btn.addEventListener('click', handleFindRole));

  // Dynamic Headline Rotator Timer
  if (!reducedMotion.matches) {
    roleTimer = window.setInterval(rotateRole, 2800);
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) {
        window.clearInterval(roleTimer);
      } else {
        window.clearInterval(roleTimer);
        roleTimer = window.setInterval(rotateRole, 2800);
      }
    });
  }
}

/* ── Ednex Academy — Automatic Mobile Role Slider ──
   Continuous, slow, seamless horizontal marquee on mobile devices (≤768px).
   - Speed: ~32-36s per complete loop (~25px/s).
   - Linear, smooth, and seamless with no card snapping or jumps.
   - Programmatically duplicates chips with aria-hidden="true" & tabindex="-1".
   - Desktop (>768px) is completely unchanged: static layout, no auto-movement.
   - Native touch swiping and drag gestures supported.
   - Pauses on touch, hover, focus, and when tab is hidden; resumes smoothly.
   - Respects prefers-reduced-motion: reduce.
   - All original chips and clones remain clickable and select the job role.
──────────────────────────────────────────────────── */
const initMobileRoleSlider = () => {
  const marqueeEl = document.querySelector('.role-chips-marquee');
  const chipsContainer = document.querySelector('.role-chips');
  if (!marqueeEl || !chipsContainer) return;

  const isMobile = () => window.innerWidth <= 768;
  const isReducedMotion = () => window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  // Programmatically clone original chips for seamless infinite loop on mobile
  const originalChips = Array.from(chipsContainer.querySelectorAll('.role-chip:not(.role-chip--clone)'));
  if (originalChips.length && !chipsContainer.querySelector('.role-chip--clone')) {
    originalChips.forEach((chip) => {
      const clone = chip.cloneNode(true);
      clone.classList.add('role-chip--clone');
      clone.setAttribute('aria-hidden', 'true');
      clone.setAttribute('tabindex', '-1');
      clone.removeAttribute('id');
      chipsContainer.appendChild(clone);
    });
  }

  let isPaused = false;
  let isInteracting = false;
  let resumeTimer = null;
  let lastTime = performance.now();
  let subpixelAccumulator = marqueeEl.scrollLeft;
  let dragStartX = 0;
  let dragStartScroll = 0;
  let isDragging = false;
  const TAP_THRESHOLD = 6;

  // Calculate distance between original Set A and duplicate Set B
  const getLoopDistance = () => {
    const firstOrig = originalChips[0];
    const firstClone = chipsContainer.querySelector('.role-chip--clone');
    if (firstOrig && firstClone) {
      return firstClone.offsetLeft - firstOrig.offsetLeft;
    }
    return 0;
  };

  const pauseSlider = () => {
    isPaused = true;
    clearTimeout(resumeTimer);
  };

  const resumeSlider = (delay = 1800) => {
    clearTimeout(resumeTimer);
    resumeTimer = setTimeout(() => {
      isPaused = false;
      isInteracting = false;
      subpixelAccumulator = marqueeEl.scrollLeft;
    }, delay);
  };

  // Continuous linear animation loop (~34s per full loop of ~890px -> ~26px/s)
  const LOOP_DURATION = 34; // seconds
  const tick = (now) => {
    const dt = Math.min((now - lastTime) / 1000, 0.1);
    lastTime = now;

    if (isMobile() && !isPaused && !isInteracting && !isReducedMotion() && !document.hidden) {
      const loopDist = getLoopDistance();
      if (loopDist > 0) {
        const speed = loopDist / LOOP_DURATION; // px per second
        subpixelAccumulator += speed * dt;

        // Wrap around seamlessly
        if (subpixelAccumulator >= loopDist) {
          subpixelAccumulator -= loopDist;
          marqueeEl.scrollLeft = subpixelAccumulator;
        } else {
          marqueeEl.scrollLeft = Math.round(subpixelAccumulator);
        }
      }
    } else {
      subpixelAccumulator = marqueeEl.scrollLeft;
    }

    requestAnimationFrame(tick);
  };

  requestAnimationFrame(tick);

  // Manual scroll event listener (syncs subpixelAccumulator and wraps seamlessly if swiped)
  marqueeEl.addEventListener('scroll', () => {
    const loopDist = getLoopDistance();
    if (loopDist > 0) {
      if (marqueeEl.scrollLeft >= loopDist + 40) {
        marqueeEl.scrollLeft -= loopDist;
        subpixelAccumulator = marqueeEl.scrollLeft;
      } else if (marqueeEl.scrollLeft < 0) {
        marqueeEl.scrollLeft += loopDist;
        subpixelAccumulator = marqueeEl.scrollLeft;
      } else if (isInteracting) {
        subpixelAccumulator = marqueeEl.scrollLeft;
      }
    }
  }, { passive: true });

  // Touch events for mobile
  marqueeEl.addEventListener('touchstart', () => {
    isInteracting = true;
    pauseSlider();
  }, { passive: true });

  marqueeEl.addEventListener('touchend', () => {
    resumeSlider(1600);
  }, { passive: true });

  marqueeEl.addEventListener('touchcancel', () => {
    resumeSlider(1600);
  }, { passive: true });

  // Hover & Focus events
  marqueeEl.addEventListener('pointerenter', pauseSlider, { passive: true });
  marqueeEl.addEventListener('pointerleave', () => resumeSlider(1200), { passive: true });
  marqueeEl.addEventListener('focusin', pauseSlider);
  marqueeEl.addEventListener('focusout', () => resumeSlider(1200));

  // Pointer drag support (works for mouse dragging on mobile simulators)
  marqueeEl.addEventListener('pointerdown', (e) => {
    if (e.button !== 0) return;
    dragStartX = e.clientX;
    dragStartScroll = marqueeEl.scrollLeft;
    isDragging = true;
    window.__roleSliderDragging = false;
    pauseSlider();
  }, { passive: true });

  marqueeEl.addEventListener('pointermove', (e) => {
    if (!isDragging) return;
    const delta = dragStartX - e.clientX;
    if (Math.abs(delta) > TAP_THRESHOLD) {
      window.__roleSliderDragging = true;
      marqueeEl.scrollLeft = dragStartScroll + delta;
      subpixelAccumulator = marqueeEl.scrollLeft;
    }
  }, { passive: true });

  const endDrag = () => {
    if (!isDragging) return;
    isDragging = false;
    subpixelAccumulator = marqueeEl.scrollLeft;
    setTimeout(() => {
      window.__roleSliderDragging = false;
    }, 100);
    resumeSlider(1800);
  };

  marqueeEl.addEventListener('pointerup', endDrag, { passive: true });
  marqueeEl.addEventListener('pointercancel', endDrag, { passive: true });

  // Tab visibility handling
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) {
      pauseSlider();
    } else {
      resumeSlider(1000);
    }
  });

  // Window resize: re-sync position and states
  window.addEventListener('resize', () => {
    if (!isMobile()) {
      marqueeEl.scrollLeft = 0;
      subpixelAccumulator = 0;
    }
  }, { passive: true });
};

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initMobileRoleSlider);
} else {
  initMobileRoleSlider();
}



// FAQ Accordion Interaction
const initFaqAccordion = () => {
  const faqItems = Array.from(document.querySelectorAll('.faq-v2-item'));
  if (!faqItems.length) return;

  const triggers = faqItems.map((item) => item.querySelector('.faq-v2-trigger')).filter(Boolean);

  faqItems.forEach((item, index) => {
    const trigger = item.querySelector('.faq-v2-trigger');
    if (!trigger) return;

    trigger.addEventListener('click', () => {
      const isCurrentlyOpen = item.classList.contains('is-open');

      // Collapse other items for clean accordion UX
      faqItems.forEach((other) => {
        if (other !== item) {
          other.classList.remove('is-open');
          const otherTrigger = other.querySelector('.faq-v2-trigger');
          if (otherTrigger) otherTrigger.setAttribute('aria-expanded', 'false');
        }
      });

      // Toggle clicked item
      if (isCurrentlyOpen) {
        item.classList.remove('is-open');
        trigger.setAttribute('aria-expanded', 'false');
      } else {
        item.classList.add('is-open');
        trigger.setAttribute('aria-expanded', 'true');
      }
    });

    // Keyboard navigation (Arrow keys, Home, End)
    trigger.addEventListener('keydown', (e) => {
      let targetIndex = null;
      if (e.key === 'ArrowDown') {
        targetIndex = (index + 1) % triggers.length;
      } else if (e.key === 'ArrowUp') {
        targetIndex = (index - 1 + triggers.length) % triggers.length;
      } else if (e.key === 'Home') {
        targetIndex = 0;
      } else if (e.key === 'End') {
        targetIndex = triggers.length - 1;
      }

      if (targetIndex !== null) {
        e.preventDefault();
        triggers[targetIndex]?.focus();
      }
    });
  });
};

