const initCookieConsent = () => {};


/**
 * ═══════════════════════════════════════════════════════════════
 * EDNEX ACADEMY — FLAT AUTOMATIC CAREER POSTER SLIDER
 * Clean horizontal slider inspired by tigerdekho.com style
 * (Strictly NO 3D, NO arrows, Auto 4.0s, Infinite loop with zero gaps)
 * ═══════════════════════════════════════════════════════════════
 */
const initCareerPosterCarousel = () => {
  const carousel = document.querySelector('.career-flat-carousel');
  if (!carousel) return;

  // Prevent duplicate initializations & multiple intervals
  if (carousel.dataset.initialized === 'true') return;
  carousel.dataset.initialized = 'true';

  const viewport = carousel.querySelector('#career-flat-viewport');
  const track = carousel.querySelector('#career-flat-track');
  const originalSlides = Array.from(carousel.querySelectorAll('.career-flat-slide'));
  const dots = Array.from(carousel.querySelectorAll('.career-flat-dot'));

  if (!originalSlides.length || !track || !viewport) return;

  const totalReal = originalSlides.length; // 8
  const CLONES_PER_SIDE = 3; // 3 clones prepended, 3 clones appended to eliminate edge gaps

  // Prepend clones of the last CLONES_PER_SIDE slides
  const headClones = [];
  for (let i = totalReal - CLONES_PER_SIDE; i < totalReal; i++) {
    const clone = originalSlides[i].cloneNode(true);
    clone.classList.add('is-clone');
    clone.classList.remove('is-active');
    clone.setAttribute('aria-hidden', 'true');
    const img = clone.querySelector('.career-flat-poster-img');
    if (img) img.setAttribute('loading', 'eager');
    const card = clone.querySelector('.career-flat-card');
    if (card) card.setAttribute('tabindex', '-1');
    headClones.push(clone);
  }
  headClones.forEach((clone) => {
    track.insertBefore(clone, originalSlides[0]);
  });

  // Append clones of the first CLONES_PER_SIDE slides
  for (let i = 0; i < CLONES_PER_SIDE; i++) {
    const clone = originalSlides[i].cloneNode(true);
    clone.classList.add('is-clone');
    clone.classList.remove('is-active');
    clone.setAttribute('aria-hidden', 'true');
    const img = clone.querySelector('.career-flat-poster-img');
    if (img) img.setAttribute('loading', 'eager');
    const card = clone.querySelector('.career-flat-card');
    if (card) card.setAttribute('tabindex', '-1');
    track.appendChild(clone);
  }

  // All slides in the DOM: headClones (3) + originalSlides (8) + tailClones (3) = 14
  const allSlides = Array.from(track.querySelectorAll('.career-flat-slide'));

  // Start at Real Slide 0 (DOM index = CLONES_PER_SIDE = 3)
  let currentDomIndex = CLONES_PER_SIDE;
  const AUTOPLAY_INTERVAL = 1000; // 1000 milliseconds (1.0 second) for faster automatic sliding
  const TRANSITION_TIMING = 'transform 0.35s cubic-bezier(0.25, 1, 0.5, 1)'; // Snappy, smooth 0.35s glide transition
  let autoplayTimer = null;
  let isHovered = false;
  let isFocused = false;
  let isTouching = false;

  // Reduced motion preference
  const motionQuery = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
  let prefersReducedMotion = motionQuery ? motionQuery.matches : false;
  if (motionQuery && motionQuery.addEventListener) {
    motionQuery.addEventListener('change', (e) => {
      prefersReducedMotion = e.matches;
      if (prefersReducedMotion) {
        stopAutoplay();
        updateSlider(false);
      } else {
        startAutoplay();
      }
    });
  }

  // Calculate real active index (0 to 7)
  const getRealIndex = () => {
    return ((currentDomIndex - CLONES_PER_SIDE) % totalReal + totalReal) % totalReal;
  };

  // Update slider position & active classes
  const updateSlider = (smooth = true) => {
    const viewportWidth = viewport.clientWidth;
    const activeSlide = allSlides[currentDomIndex];
    if (!activeSlide) return;

    // Center active slide horizontally inside viewport
    const activeOffset = activeSlide.offsetLeft;
    const activeWidth = activeSlide.offsetWidth;
    const targetX = Math.round((viewportWidth / 2) - (activeOffset + activeWidth / 2));

    track.style.transition = smooth && !prefersReducedMotion
      ? TRANSITION_TIMING
      : 'none';
    track.style.transform = `translate3d(${targetX}px, 0, 0)`;

    const realIndex = getRealIndex();

    // Update active class & accessibility on slides
    allSlides.forEach((slide, idx) => {
      const isActive = idx === currentDomIndex;
      slide.classList.toggle('is-active', isActive);
      const isClone = slide.classList.contains('is-clone');
      slide.setAttribute('aria-hidden', isActive && !isClone ? 'false' : 'true');
      const card = slide.querySelector('.career-flat-card');
      if (card) {
        card.setAttribute('tabindex', isActive && !isClone ? '0' : '-1');
      }
    });

    // Update pagination dots (Active: #0f172a, Inactive: #cbd5e1)
    dots.forEach((dot, idx) => {
      const isActive = idx === realIndex;
      dot.classList.toggle('is-active', isActive);
      dot.setAttribute('aria-selected', isActive ? 'true' : 'false');
    });
  };

  // Silently snap clones to their canonical real slides
  const normalizeClones = () => {
    let neededReset = false;
    if (currentDomIndex >= totalReal + CLONES_PER_SIDE) {
      currentDomIndex -= totalReal;
      neededReset = true;
    } else if (currentDomIndex < CLONES_PER_SIDE) {
      currentDomIndex += totalReal;
      neededReset = true;
    }
    if (neededReset) {
      updateSlider(false);
      void track.offsetHeight;
    }
  };

  // Handle transition end for seamless infinite wrap
  track.addEventListener('transitionend', (e) => {
    if (e.target !== track || e.propertyName !== 'transform') return;
    normalizeClones();
  });

  // User jumps to specific real slide via dot navigation
  const goToRealSlide = (realIdx) => {
    currentDomIndex = realIdx + CLONES_PER_SIDE;
    updateSlider(true);
    restartAutoplay();
  };

  // Internal auto-advance: smoothly steps forward
  const advanceNext = () => {
    currentDomIndex += 1;
    updateSlider(true);
  };

  // Check if autoplay should pause
  const shouldPause = () => {
    return isHovered || isFocused || isTouching || document.hidden || prefersReducedMotion;
  };

  // Start autoplay with strict single timer
  const startAutoplay = () => {
    stopAutoplay();
    if (shouldPause()) return;
    autoplayTimer = setInterval(() => {
      if (!shouldPause()) {
        advanceNext();
      }
    }, AUTOPLAY_INTERVAL);
  };

  // Clear autoplay timer safely
  const stopAutoplay = () => {
    if (autoplayTimer) {
      clearInterval(autoplayTimer);
      autoplayTimer = null;
    }
  };

  // Reset autoplay timer countdown (e.g., after user interaction)
  const restartAutoplay = () => {
    stopAutoplay();
    startAutoplay();
  };

  // Dot navigation
  dots.forEach((dot, idx) => {
    dot.addEventListener('click', (e) => {
      e.preventDefault();
      goToRealSlide(idx);
    });
  });

  // Slide click delegation: clicking adjacent preview jumps to it; active card follows course link
  track.addEventListener('click', (e) => {
    const slide = e.target.closest('.career-flat-slide');
    if (!slide) return;
    const clickedIndex = allSlides.indexOf(slide);
    if (clickedIndex !== -1 && clickedIndex !== currentDomIndex) {
      e.preventDefault();
      currentDomIndex = clickedIndex;
      updateSlider(true);
      restartAutoplay();
    }
  });

  // Touch swipe support on mobile
  let touchStartX = 0;
  let touchStartY = 0;
  let touchEndX = 0;

  viewport.addEventListener('touchstart', (e) => {
    if (!e.touches.length) return;
    isTouching = true;
    stopAutoplay();
    touchStartX = e.touches[0].clientX;
    touchStartY = e.touches[0].clientY;
  }, { passive: true });

  viewport.addEventListener('touchend', (e) => {
    if (!e.changedTouches.length) return;
    isTouching = false;
    touchEndX = e.changedTouches[0].clientX;
    const deltaX = touchEndX - touchStartX;
    const deltaY = Math.abs(e.changedTouches[0].clientY - touchStartY);

    if (Math.abs(deltaX) > 35 && Math.abs(deltaX) > deltaY) {
      if (deltaX < 0) {
        currentDomIndex += 1;
      } else {
        currentDomIndex -= 1;
      }
      updateSlider(true);
      restartAutoplay();
    } else {
      restartAutoplay();
    }
  }, { passive: true });

  viewport.addEventListener('touchcancel', () => {
    isTouching = false;
    restartAutoplay();
  }, { passive: true });

  // Hover pause & resume
  carousel.addEventListener('mouseenter', () => {
    isHovered = true;
    stopAutoplay();
  });

  carousel.addEventListener('mouseleave', () => {
    isHovered = false;
    if (!shouldPause()) {
      startAutoplay();
    }
  });

  // Focus pause & resume
  carousel.addEventListener('focusin', () => {
    isFocused = true;
    stopAutoplay();
  });

  carousel.addEventListener('focusout', (e) => {
    if (!carousel.contains(e.relatedTarget)) {
      isFocused = false;
      if (!shouldPause()) {
        startAutoplay();
      }
    }
  });

  // Page visibility change (pause in background tab, resume in active tab)
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) {
      stopAutoplay();
    } else if (!shouldPause()) {
      startAutoplay();
    }
  });

  // Keyboard navigation
  carousel.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowLeft') {
      e.preventDefault();
      currentDomIndex -= 1;
      updateSlider(true);
      restartAutoplay();
    } else if (e.key === 'ArrowRight') {
      e.preventDefault();
      currentDomIndex += 1;
      updateSlider(true);
      restartAutoplay();
    }
  });

  // Window resize handler (debounced repositioning without resetting timer)
  let resizeTimer = null;
  window.addEventListener('resize', () => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
      normalizeClones();
      updateSlider(false);
    }, 100);
  });

  // Re-verify centering after window and images are fully loaded
  window.addEventListener('load', () => {
    updateSlider(false);
  });

  // Initial render (double-frame to ensure layout geometries are stable)
  requestAnimationFrame(() => {
    updateSlider(false);
    setTimeout(() => updateSlider(false), 80);
  });

  // Start consistent 4-second autoplay
  startAutoplay();
};

